import { test, expect } from '@playwright/test';

test.describe('Search - No Results Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display "No results found" message when search returns no items', async ({ page }) => {
    // Intercept the search API call
    await page.route('**/api/search*', (route) => {
      route.abort('blockedbyclient');
    });

    // Perform search with no matching items
    const searchInput = page.getByPlaceholder('Search items...');
    await searchInput.fill('nonexistentitem123');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for the API response
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify the "No results found" message is visible
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify the results list is empty
    const resultsContainer = page.locator('[data-testid="results-container"]');
    await expect(resultsContainer).toBeVisible();
    await expect(resultsContainer).not.toContainText(/item/i);

    // Verify the search input still contains the query
    await expect(searchInput).toHaveValue('nonexistentitem123');

    // Verify the search button is still enabled
    await expect(searchButton).toBeEnabled();
  });

  test('should hide "No results found" message when search returns items', async ({ page }) => {
    // Intercept the search API call and return mock data
    await page.route('**/api/search*', (route) => {
      route.continue({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          items: [
            { id: 1, name: 'Item A', price: 10 },
            { id: 2, name: 'Item B', price: 20 },
          ],
          total: 2,
        }),
      });
    });

    // Perform search with matching items
    const searchInput = page.getByPlaceholder('Search items...');
    await searchInput.fill('item');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for the API response
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify the "No results found" message is NOT visible
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).not.toBeVisible();

    // Verify results are displayed
    const resultsContainer = page.locator('[data-testid="results-container"]');
    await expect(resultsContainer).toBeVisible();

    // Verify results list contains items
    const resultItems = page.locator('[data-testid="result-item"]');
    await expect(resultItems).toHaveCount(2);

    // Verify item names are visible
    const itemAName = page.getByText('Item A');
    const itemBName = page.getByText('Item B');
    await expect(itemAName).toBeVisible();
    await expect(itemBName).toBeVisible();

    // Verify pagination controls are visible
    const pagination = page.locator('[data-testid="pagination"]');
    await expect(pagination).toBeVisible();
  });
});
